package rules

import "testing"

// Cases ported from PHP-CS-Fixer's tests/Fixer/ClassNotation/NoPhp4ConstructorFixerTest.php (v3.95.27).
func TestNoPhp4ConstructorUpstream(t *testing.T) {
	t.Parallel()
	runUpstreamCases(t, NoPhp4Constructor{}, noPhp4ConstructorUpstreamCases)
}

